import 'package:flutter/material.dart';
import 'evaluation_subject.dart';
class EvaluationSubjectsScreen extends StatefulWidget { const EvaluationSubjectsScreen({super.key}); @override State<EvaluationSubjectsScreen> createState()=>_State(); }
class _State extends State<EvaluationSubjectsScreen>{ String filter='Tous'; @override Widget build(BuildContext c){ final xs=preloadedSubjects.where((s)=>filter=='Tous'||s.level.contains(filter)).toList(); return Scaffold(backgroundColor:const Color(0xff263238),appBar:AppBar(title:const Text('Sujets d’évaluation'),backgroundColor:const Color(0xff263238),actions:[IconButton(icon:const Icon(Icons.print),onPressed:()=>_print(c))]),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:DropdownButton<String>(value:filter,items:['Tous','1ère','Tle'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>filter=v!))),Expanded(child:ListView(children:xs.map((s)=>Card(child:ListTile(title:Text(s.title),subtitle:Text(s.discipline),onTap:()=>showDialog(context:c,builder:(_)=>AlertDialog(title:Text(s.title),content:SingleChildScrollView(child:Text('${s.statement}\n\nCritères APC\n${s.criteria}')),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Fermer'))])))).toList()))]); } void _print(BuildContext c)=>ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Sujet prêt à être imprimé ou exporté.'))); }
